import threading
import time

threads = []
event = threading.Event()

def target_function():
    event.wait()

print("Starting to create threads...")
try:
    while True:
        t = threading.Thread(target=target_function)
        t.start()
        threads.append(t)
        if len(threads) % 500 == 0:
            print(f"Created {len(threads)} threads...")
except RuntimeError as e:
    print(f"Encountered system limit. Failed after creating {len(threads)} threads.")
    print(f"Error: {e}")
except Exception as e:
    print(f"Other error after creating {len(threads)} threads. Error: {e}")

time.sleep(2)

arguments.command:
cat << 'EOF' > thread_limit.c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* thread_target(void* arg) {
    pthread_mutex_lock(&mutex);
    // Wait forever on a synchronization primitive
    pthread_cond_wait(&cond, &mutex);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    int max_threads = 200000; // Above kernel thread limit
    pthread_t *threads = malloc(sizeof(pthread_t) * max_threads);
    if (!threads) {
        perror("malloc");
        return 1;
    }

    int count = 0;
    while (count < max_threads) {
        int ret = pthread_create(&threads[count], NULL, thread_target, NULL);
        if (ret != 0) {
            printf("Encountered system limit at thread %d. Error: %s\n", count, strerror(ret));
            break;
        }
        count++;
        if (count % 5000 == 0) {
            printf("Created %d threads...\n", count);
        }
    }

    printf("Keeping %d threads alive in memory for 15 seconds to observe scheduler...\n", count);
    sleep(15);

    return 0;
}
EOF
gcc -o thread_limit thread_limit.c -pthread
./thread_limit > thread_output.txt &
PID=$!
sleep 5
echo "--- UPTIME & LOAD ---"
uptime
echo "--- TOP OUTPUT ---"
top -b -n 1 | head -n 20
echo "--- DMESG LOGS ---"
dmesg | grep -i -E "thread|resource|fork|limit|out of memory|oom|pid" | tail -n 20
kill $PID
echo "--- THREAD PROGRAM OUTPUT ---"
cat thread_output.txt
